$ErrorActionPreference = 'Stop'
if (-not $env:CHEMSEP_REFERENCE_SOURCE) { throw 'Set CHEMSEP_REFERENCE_SOURCE to the installed reference source directory' }
$Root = 'C:\iterate-hackathon\reference-replay'
New-Item -ItemType Directory -Force -Path $Root | Out-Null
[IO.File]::WriteAllBytes((Join-Path $Root 'replay_reference.py'), [Convert]::FromBase64String(''))
[IO.File]::WriteAllBytes((Join-Path $Root 'authors_design_reference.json'), [Convert]::FromBase64String(''))
& 'C:\chemsep-benchmark\venv\Scripts\python.exe' (Join-Path $Root 'replay_reference.py') --upstream $env:CHEMSEP_REFERENCE_SOURCE --reference (Join-Path $Root 'authors_design_reference.json') --out (Join-Path $Root 'reference-20261114.json')
if ($LASTEXITCODE -ne 0) { throw 'Reference replay failed; inspect preserved call trace' }
